9	/**
10	 * Builds the owner's {@code customerCode}, the single region-and-hash identity every other derived
11	 * value hangs off. The code is {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived
12	 * from the postcode (falling back to the city, see {@link Localities}) and {@code HASH8} is the first
13	 * eight upper-case hex characters of {@code SHA-256(normalizedTelephone + lastName)}.
14	 *
15	 * <p>The telephone is already normalized to E.164 by the time an owner is built, so the hash is stable
16	 * for a given owner regardless of how the telephone was typed. Because the region prefix is exactly the
17	 * owner's locality, {@link #localityOf(Owner)} reads it straight back off the code.
18	 */
19	public final class CustomerCodes {
20	
21	    private CustomerCodes() {
22	    }
23	
24	    /** The {@code '<REGION>-<HASH8>'} customer code for {@code owner}. */
25	    public static String of(Owner owner) {
26	        return Localities.of(owner.getPostcode(), owner.getCity()) + "-"
27	                + hash8(owner.getTelephone(), owner.getLastName());
28	    }
29	
30	    /**
31	     * De-duplicates {@code code} against {@code taken}: if no existing owner already uses it the code
32	     * is returned unchanged, otherwise {@code '-<n>'} is appended with the smallest {@code n >= 2}
33	     * that makes the result unique (e.g. {@code 'NSW-1A2B3C4D-2'}).
34	     */
35	    public static String deduplicate(String code, java.util.Collection<String> taken) {
36	        if (!taken.contains(code)) {
37	            return code;
38	        }
39	        for (int n = 2; ; n++) {
40	            String candidate = code + "-" + n;
41	            if (!taken.contains(candidate)) {
42	                return candidate;
43	            }
44	        }
45	    }
46	
47	    /**
48	     * The first eight upper-case hex characters of {@code SHA-256(telephone + lastName)}, over the
49	     * UTF-8 bytes of the concatenation. A {@code null} component contributes nothing.
50	     */
51	    public static String hash8(String telephone, String lastName) {
52	        String input = safe(telephone) + safe(lastName);
53	        byte[] digest = sha256(input.getBytes(StandardCharsets.UTF_8));
54	        StringBuilder sb = new StringBuilder(8);
55	        for (int i = 0; i < 4; i++) {
56	            sb.append(String.format("%02X", digest[i]));
57	        }
58	        return sb.toString();
59	    }
60	
61	    /**
62	     * The owner's locality: the {@code REGION} prefix of its customer code, or, when the code has not
63	     * been assigned yet, the region derived directly from the postcode and city.
64	     */
65	    public static String localityOf(Owner owner) {
66	        String code = owner.getCustomerCode();
67	        if (code != null) {
68	            int dash = code.indexOf('-');
69	            if (dash > 0) {
70	                return code.substring(0, dash);
71	            }
72	        }
73	        return Localities.of(owner.getPostcode(), owner.getCity());
74	    }
75	
76	    private static byte[] sha256(byte[] bytes) {
77	        try {
78	            return MessageDigest.getInstance("SHA-256").digest(bytes);
79	        }
80	        catch (NoSuchAlgorithmException ex) {
81	            throw new IllegalStateException("SHA-256 not available", ex);
82	        }
83	    }
84	
85	    private static String safe(String value) {
86	        return value == null ? "" : value;
87	    }
88	}
